@php
    $activeSection = 'assets';
    $pageTitle = 'Assets & Equipment';
    $pageDescription = 'View customer assets, equipment condition and maintenance information in one workspace.';
    $assetCollection = collect($assets ?? []);
    $totalAssets = $assetCollection->count();
    $operationalAssets = $assetCollection->filter(fn($a) => in_array(strtolower((string)($a->operational_status ?? $a->status ?? '')), ['operational','active','running','available']))->count();
    $maintenanceAssets = $assetCollection->filter(fn($a) => str_contains(strtolower((string)($a->operational_status ?? $a->status ?? '')), 'maint'))->count();
    $stoppedAssets = $assetCollection->filter(fn($a) => in_array(strtolower((string)($a->operational_status ?? $a->status ?? '')), ['stopped','out of service','inactive','down','fault']))->count();
    $otherAssets = max(0, $totalAssets - $operationalAssets - $maintenanceAssets - $stoppedAssets);
    $categoryCounts = $assetCollection->groupBy(fn($a) => $a->category?->name ?? $a->category_name ?? $a->type ?? 'Other')->map->count()->sortDesc();
    $recentAssets = $assetCollection->sortByDesc('updated_at')->take(4);
@endphp

