<script>(()=>{const search=document.getElementById('asset-search'),site=document.getElementById('asset-site-filter'),tabs=[...document.querySelectorAll('.asset-tab')],rows=[...document.querySelectorAll('#asset-table-body tr[data-status]')];let status='all';const apply=()=>{const q=(search?.value||'').trim().toLowerCase(),s=(site?.value||'').trim().toLowerCase();rows.forEach(row=>{const visible=(status==='all'||row.dataset.status===status)&&(!q||row.dataset.search.includes(q))&&(!s||row.dataset.site===s);row.style.display=visible?'':'none'});};tabs.forEach(tab=>tab.addEventListener('click',()=>{tabs.forEach(x=>x.classList.remove('active'));tab.classList.add('active');status=tab.dataset.filter;apply()}));search?.addEventListener('input',apply);site?.addEventListener('change',apply);})();</script>
@endpush

